-- Antiguo nivel «Cada célula, su función» (Glía del SNC, practica_niveles id 3). Reservado para «La glía en acción».
INSERT OR IGNORE INTO practica_niveles (id, actividad_id, numero, titulo, instrucciones, tipo, activo) VALUES
  (3, 10, 2, 'Cada célula, su función', 'Lee la frase y toca la tarjeta de la célula glial que describe. <strong>Verde</strong>: correcta al primer intento. <strong>Rojo</strong>: esa tarjeta no era; lee la pista y prueba con otra.', 'elegir', 1);
INSERT OR IGNORE INTO practica_items (nivel_id, enunciado, respuesta, sinonimos, pista, explicacion, orden, fila, celda, nota) VALUES
  (3, 'Es la glía más abundante del SNC; sus pies perivasculares rodean los capilares.', 'Astrocito', 'astrocitos|astroglia|astrocito reactivo|astrocitos reactivos',
      'Su nombre viene de su forma de estrella; su marcador clásico es la GFAP.',
      'Sus pies perivasculares inducen y mantienen la barrera hematoencefálica, aunque el sello lo forman las uniones estrechas del endotelio.', 1, NULL, NULL, 'Protoplasmático (sustancia gris, contacta sinapsis) · fibroso (sustancia blanca, contacta nodos de Ranvier).'),
  (3, 'Recapta el glutamato liberado en la sinapsis, lo transforma en glutamina y se la devuelve a la neurona.', 'Astrocito', 'astrocitos|astroglia|astrocito reactivo|astrocitos reactivos',
      'Es la tercera parte de la sinapsis tripartita.',
      'Ciclo glutamato-glutamina. Si falla, el glutamato se acumula y daña a la neurona (excitotoxicidad).', 2, NULL, NULL, NULL),
  (3, 'Con varias prolongaciones forma la mielina de hasta unos 50 axones del SNC.', 'Oligodendrocito', 'oligodendrocitos|oligodendroglia|oligo',
      'Es la célula que mieliniza en el sistema nervioso central.',
      'Cada prolongación forma un internodo en un axón distinto. Su mielina tiene sobre todo PLP.', 3, NULL, NULL, NULL),
  (3, 'Es la célula inmune residente del SNC: vigila el tejido, fagocita restos y poda sinapsis.', 'Microglía', 'microglia|microglias|microgliocito|microgliocitos|celula microglial|celulas microgliales',
      'Su origen no es nervioso: deriva de células del sistema inmune que colonizan el SNC.',
      'Aunque se diga que está «en reposo», sus prolongaciones exploran el tejido todo el tiempo.', 4, NULL, NULL, NULL),
  (3, 'Epitelio cúbico ciliado que tapiza los ventrículos y el canal central de la médula.', 'Célula ependimaria', 'ependimaria|ependimarias|celulas ependimarias|ependimocito|ependimocitos|ependimo|epitelio ependimario',
      'Es la única glía con forma de epitelio.',
      'Sus cilios mueven el LCR y sus uniones forman la barrera entre el LCR y el tejido nervioso.', 5, NULL, NULL, NULL),
  (3, 'Tras una lesión del SNC se vuelve reactivo y forma una cicatriz que protege el tejido sano, pero impide que los axones vuelvan a crecer.', 'Astrocito', 'astrocitos|astroglia|astrocito reactivo|astrocitos reactivos',
      'Es la misma célula que regula la barrera y el glutamato, ahora en estado reactivo.',
      'Gliosis reactiva: la cicatriz glial aísla la lesión, pero es una de las razones por las que el SNC casi no regenera.', 6, NULL, NULL, NULL),
  (3, 'En la esclerosis múltiple, el sistema inmune destruye la mielina que forman los {}.', 'Oligodendrocito', 'oligodendrocitos|oligodendroglia|oligo',
      'La esclerosis múltiple afecta el SNC, no los nervios periféricos.',
      'Sin mielina la conducción se enlentece o se bloquea: fatiga, torpeza motora y alteraciones sensitivas.', 7, NULL, NULL, NULL),
  (3, 'En los plexos coroideos, estas células producen el líquido cefalorraquídeo.', 'Célula ependimaria', 'ependimaria|ependimarias|celulas ependimarias|ependimocito|ependimocitos|ependimo|epitelio ependimario',
      'Son las mismas células que tapizan los ventrículos.',
      'Las ependimarias de los plexos coroideos producen el LCR y regulan su composición iónica.', 8, NULL, NULL, NULL),
  (3, 'Según lo que detecta, pasa de un estado de vigilancia a uno activado: proinflamatorio (M1) o reparador (M2).', 'Microglía', 'microglia|microglias|microgliocito|microgliocitos|celula microglial|celulas microgliales',
      'Es la célula inmune del SNC.',
      'M1 fagocita y secreta citoquinas proinflamatorias; M2 secreta factores neurotróficos y ayuda a resolver la inflamación.', 9, NULL, NULL, NULL),
  (3, 'Durante el desarrollo, la glía radial guía la migración de las neuronas y al madurar se transforma en {}.', 'Astrocito', 'astrocitos|astroglia|astrocito reactivo|astrocitos reactivos',
      'Es la glía más abundante del SNC adulto.',
      'Las prolongaciones de la glía radial son los «rieles» desde la zona ventricular hasta la corteza.', 10, NULL, NULL, NULL);
